// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;

    struct Policy {
        bool blockAssertion;
        bool arbitrateViaEscalationManager;
        bool discardOracle;
        bool validateDisputers;
    }

    function setUp() public { c = new BaseEscalationManager(address(new __InvMutHandleStub())); }

    function testFuzz_property(bytes32 assertionId) public {
        bytes memory ret = abi.encode(c.getAssertionPolicy(assertionId));
        Policy memory p = abi.decode(ret, (Policy));
        assertTrue(
            !p.blockAssertion &&
            !p.arbitrateViaEscalationManager &&
            !p.discardOracle &&
            !p.validateDisputers,
            "all assertion policy flags must be false"
        );
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
